"""i18n-2 一次性生成脚本：按 zh-CN.ts 键序产出 7 个新语言目录（运行后可删）。"""
import io, json, re, os

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))

zh_src = io.open(os.path.join(ROOT, 'src/lib/i18n/zh-CN.ts'), encoding='utf-8').read()
sections = {}
cur = None
for line in zh_src.splitlines():
    m = re.match(r'  (\w+): \{', line)
    if m:
        cur = m.group(1); sections[cur] = []
    elif cur and re.match(r'    (\w+):', line):
        sections[cur].append(re.match(r'    (\w+):', line).group(1))

