def emit(locale, data, comment):
    keys = {'panel': sections['panel'], 'settings': sections['settings'], 'onb': sections['onb'], 'err': sections['err']}
    lines = ['// ' + comment, "import type { zh } from './zh-CN';", '', 'export const %s: typeof zh = {' % locale]
    for sec in ['panel', 'settings', 'onb', 'err']:
        lines.append('  %s: {' % sec)
        for key in keys[sec]:
            if key in NATIVE and NATIVE[key] is not None:
                val = NATIVE[key]
            elif key == 'langSystem':
                val = data[sec]['langSystem']
            else:
                val = data[sec][key]
            lines.append('    %s: %s,' % (key, json.dumps(val, ensure_ascii=False)))
        lines.append('  },')
    lines.append('};')
    path = os.path.join(ROOT, 'src/lib/i18n/%s.ts' % locale)
    io.open(path, 'w', encoding='utf-8', newline='\n').write('\n'.join(lines) + '\n')
    print('written', path)

